using System;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace IDSketcher {
partial class Studio {
 ComboBox vectorMode=new ComboBox();TextBox colourEntry=new TextBox();Label colourEntryHint=new Label();
 void PreviewNewFeatures(){
  AddTypedLayer(true);var layer=canvas.Doc.Selected;layer.Vectors.Add(new VectorShape{Kind="Line",Colour=Color.Teal,Width=8,Points=new System.Collections.Generic.List<PointF>{new PointF(200,300),new PointF(1050,500)}});layer.Vectors.Add(new VectorShape{Kind="Ellipse",Colour=Color.SteelBlue,Width=12,Points=new System.Collections.Generic.List<PointF>{new PointF(850,300),new PointF(1400,700)}});layer.Vectors.Add(new VectorShape{Kind="Polygon",Colour=Color.IndianRed,Width=10,Points=new System.Collections.Generic.List<PointF>{new PointF(450,800),new PointF(1050,850),new PointF(1100,1350),new PointF(300,1300)}});layer.Vectors[1].Rotate(25);layer.InvalidateVectors();vectorMode.SelectedItem="Select/edit";var pick=layer.Vectors[1].Grips()[0];var offset=canvas.Offset;var screen=Point.Round(new PointF(offset.X+pick.X*canvas.Zoom,offset.Y+pick.Y*canvas.Zoom));canvas.TestDrag(screen,screen);
  using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"vector-tools-preview.png"));}
  layer.Visible=false;canvas.Doc.Active=0;RefreshLayers();guideMode.SelectedItem="Ellipse";canvas.SetEllipseRotation(35);editGuide.Checked=true;
  using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"rotated-guide-preview.png"));}guideMode.SelectedItem="Freehand";canvas.SetEllipseRotation(0);
 }
 static Bitmap PickerImage(int size=24){var b=new Bitmap(size,size);using(var g=Graphics.FromImage(b)){g.ScaleTransform(size/24f,size/24f);g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;Point[] points={new Point(4,2),new Point(4,20),new Point(9,15),new Point(13,23),new Point(17,21),new Point(13,13),new Point(21,13)};g.FillPolygon(Brushes.White,points);g.DrawPolygon(Pens.Black,points);}return b;}
 void AddVectorTools(FlowLayoutPanel tools){
  int first=tools.Controls.Count;vectorPicker=Theme.Button("Select / edit   V",delegate{canvas.AcceptVectorDraft();vectorMode.SelectedItem="Select/edit";canvas.SetSelectionMode("Draw");UpdateVectorButtons();UpdateSelectionButtons();canvas.Focus();});vectorPicker.Width=170;vectorPicker.Image=PickerImage();vectorPicker.ImageAlign=ContentAlignment.MiddleLeft;vectorPicker.TextAlign=ContentAlignment.MiddleRight;tools.Controls.Add(vectorPicker);
  vectorMode.DropDownStyle=ComboBoxStyle.DropDownList;vectorMode.Width=160;vectorMode.Items.AddRange(new object[]{"Line","Ellipse","Rectangle","Polygon","Polyline","Vector pen","Curvature pen","Freehand","Select/edit"});
  vectorMode.SelectedIndexChanged+=delegate{if(canvas.Doc!=null&&!canvas.Doc.Selected.IsVector)return;if(vectorMode.Text=="Select/edit")canvas.AcceptVectorDraft();canvas.EndStroke();canvas.ResetShift();canvas.CancelVector();canvas.VectorMode=vectorMode.Text;canvas.SetSelectionMode("Draw");if(vectorMode.Text=="Rectangle"||vectorMode.Text=="Polygon"){loadingVectorStyle=true;vectorTaper.Value=0;canvas.VectorTaper=0;loadingVectorStyle=false;}UpdateVectorButtons();UpdateSelectionButtons();UpdateStatus();canvas.Focus();canvas.RefreshCursor();};vectorMode.SelectedItem="Select/edit";AddVectorButtons(tools);AddPointSpacing(tools);
  tools.Controls.Add(new Label{Text="WEIGHT / STROKE · PX",Width=170,Height=23});vectorWidth.DecimalPlaces=2;vectorWidth.Minimum=.25m;vectorWidth.Maximum=500;vectorWidth.Value=5;vectorWidth.Width=150;vectorWidth.ValueChanged+=delegate{if(!loadingVectorStyle)canvas.ChangeVectorWeight((float)vectorWidth.Value);else canvas.VectorWidth=(float)vectorWidth.Value;};tools.Controls.Add(vectorWidth);AddVectorTaper(tools);
  tools.Controls.Add(new Label{Text="SHAPE OPACITY · %",Width=170,Height=23});vectorOpacity.Minimum=0;vectorOpacity.Maximum=100;vectorOpacity.Value=100;vectorOpacity.Width=150;vectorOpacity.ValueChanged+=delegate{canvas.VectorOpacity=(float)vectorOpacity.Value/100;if(!loadingVectorStyle)canvas.ChangeVectorOpacity(canvas.VectorOpacity);};tools.Controls.Add(vectorOpacity);
  tools.Controls.Add(new Label{Text="POLYGON SIDES · 3–24",Width=170,Height=23});polygonSides.Minimum=3;polygonSides.Maximum=20;polygonSides.Value=6;polygonSides.Width=150;polygonSides.ValueChanged+=delegate{if(!loadingVectorStyle)canvas.ChangePolygonSides((int)polygonSides.Value);else canvas.PolygonSides=(int)polygonSides.Value;};tools.Controls.Add(polygonSides);
  AddFillControls(tools);canvas.PointSelectionChanged=UpdatePointButtons;AddSimplifyButton(tools);var style=copyStyleButton=Theme.Button("COPY STYLE",delegate{canvas.CopySelectedStyle();});style.Width=160;style.TextAlign=ContentAlignment.MiddleCenter;tools.Controls.Add(style);AddBooleanControls(tools);
  for(int i=first;i<tools.Controls.Count;i++)vectorControls.Add(tools.Controls[i]);
 }
 void AddColourEntry(Panel colour){colourEntry.SetBounds(0,350,106,25);colour.Controls.Add(colourEntry);var apply=Theme.Button("APPLY",delegate{ApplyColourEntry();});apply.SetBounds(110,348,60,28);colour.Controls.Add(apply);var add=Theme.Button("ADD",delegate{AddPaletteColour();});add.SetBounds(174,348,58,28);colour.Controls.Add(add);colourEntry.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Enter){ApplyColourEntry();e.SuppressKeyPress=true;}};colourEntryHint.SetBounds(0,379,240,25);colour.Controls.Add(colourEntryHint);}
 void UpdateColourEntry(){Color c=canvas.Ink;colourEntry.Text="#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2");colourEntryHint.Text="";colourEntry.BackColor=Theme.Light?Color.White:Theme.Bg;}
 void ApplyColourEntry(){try{Color colour=ParseColour(colourEntry.Text,"HEX");canvas.Ink=colour;wheel.SetColor(colour);SyncColour();canvas.ApplyVectorColour();}catch{colourEntry.BackColor=Color.MistyRose;colourEntryHint.Text="Check values and press Apply again.";}}
 static Color ParseColour(string text,string format){if(format=="HEX"){string t=text.Trim().TrimStart('#');if(t.Length!=6)throw new FormatException();int n=int.Parse(t,NumberStyles.HexNumber,CultureInfo.InvariantCulture);return Color.FromArgb((n>>16)&255,(n>>8)&255,n&255);}string[] parts=text.Split(new[]{',',';',' '},StringSplitOptions.RemoveEmptyEntries);int count=3;if(parts.Length!=count)throw new FormatException();double[] v=new double[count];for(int i=0;i<count;i++){v[i]=double.Parse(parts[i].Trim().TrimEnd('%'),CultureInfo.InvariantCulture);if(double.IsNaN(v[i])||v[i]<0||v[i]>(format=="HSV"?(i==0?360:100):255))throw new FormatException();}if(format=="HSV")return Wheel.Hsv(v[0]%360,v[1]/100,v[2]/100);return Color.FromArgb((int)Math.Round(v[0]),(int)Math.Round(v[1]),(int)Math.Round(v[2]));}
}
}
